-- Machining - Plunge Milling, Plunge Step Ratio = 0.75. Sandvik Coromant, Plunge milling
-- (sandvik.coromant.com/en-gb/knowledge/milling/milling-holes-cavities-pockets/plunge-milling):
-- step 's = 75% DC' for a cutter overhang up to 3 x DC (50 % at a longer overhang). The workbook's
-- Plunge Milling sheet has no plunge step.
--
-- Machining - Plunge Milling, Approach Length = 10. the Machining calculator workbook
-- (memory/Machining - Calculator Database (1).xlsx), Plunge Milling sheet: the length of cut plus
-- 10 mm for the cutter's approach and overrun (Plunge Milling!G19).
--
-- Requires migration 804. Self-contained, idempotent, post-checked.

BEGIN;

-- Machining - Drilling
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Machining - Drilling$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Machining - Drilling$q$, 'process', 'single', false, true, true, $q$Drilling a hole as the Machining calculator workbook's Drilling sheet times it: n = 1000 v / (pi D), capped at the machine's spindle limit; time = (hole depth + 10 mm) / (feed x n), rounded up to whole seconds a hole. Cutting speed (a range, picked at the Range Position) and the feed of the hole diameter's band from the workbook's drilling and reaming table for the material; drill price and life from the sheet.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$Drilling a hole as the Machining calculator workbook's Drilling sheet times it: n = 1000 v / (pi D), capped at the machine's spindle limit; time = (hole depth + 10 mm) / (feed x n), rounded up to whole seconds a hole. Cutting speed (a range, picked at the Range Position) and the feed of the hole diameter's band from the workbook's drilling and reaming table for the material; drill price and life from the sheet.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Hole Diameter$q$, $q$Hole Diameter (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Hole Depth$q$, $q$Hole Depth (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Holes$q$, $q$Holes$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Speed Min$q$, $q$Speed Min (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblDrillReamData$q$, $q$SpeedMinMPerMin$q$, NULL, 4, true),
    (v_id, $q$Speed Max$q$, $q$Speed Max (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblDrillReamData$q$, $q$SpeedMaxMPerMin$q$, NULL, 5, true),
    (v_id, $q$Feed$q$, $q$Feed (mm/rev)$q$, $q$number$q$, $q$mm/rev$q$, $q$machining_lookup$q$, $q$tblDrillReamData$q$, $q$FeedMmPerRev$q$, NULL, 6, true),
    (v_id, $q$Range Position$q$, $q$Range Position$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$0.3$q$, 7, true),
    (v_id, $q$Max Spindle Speed$q$, $q$Max Spindle Speed (rpm)$q$, $q$number$q$, $q$rpm$q$, NULL, NULL, NULL, NULL, 8, true),
    (v_id, $q$Approach Length$q$, $q$Approach Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, $q$10$q$, 9, true),
    (v_id, $q$Cutting Speed$q$, $q$Cutting Speed (m/min)$q$, $q$calculated$q$, $q$m/min$q$, NULL, NULL, NULL, $q${Speed Min} + {Range Position} * ({Speed Max} - {Speed Min})$q$, 10, false),
    (v_id, $q$Spindle Speed$q$, $q$Spindle Speed (rpm)$q$, $q$calculated$q$, $q$rpm$q$, NULL, NULL, NULL, $q$min({Max Spindle Speed}, {Cutting Speed} * 1000 / (pi * {Hole Diameter}))$q$, 11, false),
    (v_id, $q$Machining Time$q$, $q$Machining Time (min)$q$, $q$calculated$q$, $q$min$q$, NULL, NULL, NULL, $q$({Hole Depth} + {Approach Length}) / ({Feed} * {Spindle Speed})$q$, 12, false),
    (v_id, $q$Time per Hole$q$, $q$Time per Hole (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$ceil({Machining Time} * 60)$q$, 13, false),
    (v_id, $q$Tool Price$q$, $q$Tool Price (INR)$q$, $q$number$q$, $q$INR$q$, $q$machining_lookup$q$, $q$tblCuttingToolCost$q$, $q$PriceInr$q$, NULL, 14, true),
    (v_id, $q$Tool Life$q$, $q$Tool Life (parts)$q$, $q$number$q$, $q$parts$q$, $q$machining_lookup$q$, $q$tblCuttingToolCost$q$, $q$ToolLifeParts$q$, NULL, 15, true),
    (v_id, $q$Tool Cost per Part$q$, $q$Tool Cost per Part (INR)$q$, $q$calculated$q$, $q$INR$q$, NULL, NULL, NULL, $q${Tool Price} / {Tool Life}$q$, 16, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Holes} * {Time per Hole}$q$, 17, false);

  INSERT INTO public.process_calculator_mappings
    (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
  SELECT 'Machining', s.station, $q$Drilling$q$, v_id, $q$Machining - Drilling$q$, true, 700, s.cls,
         (SELECT pt.id FROM public.process_taxonomy pt WHERE pt.process_group = 'Machining' AND pt.process_name = s.station LIMIT 1)
  FROM (VALUES ($q$2_axis_lathe$q$, $q$2 Axis Lathe$q$), ($q$3_axis_lathe$q$, $q$3 Axis Lathe$q$), ($q$2_axis_bar_feed_lathe_with_sub_spindle$q$, $q$2 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$3_axis_bar_feed_lathe_with_sub_spindle$q$, $q$3 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$simultaneous_turning$q$, $q$Simultaneous Turning$q$), ($q$machining_millturn$q$, $q$MillTurn$q$), ($q$3_axis_mill$q$, $q$3 Axis Mill$q$), ($q$4_axis_mill$q$, $q$4 Axis Mill$q$), ($q$5_axis_mill$q$, $q$5 Axis Mill$q$)) AS s(cls, station)
  ON CONFLICT (process_group, process_route, operation) DO UPDATE
  SET calculator_id = EXCLUDED.calculator_id,
      calculator_name = EXCLUDED.calculator_name,
      machine_class = EXCLUDED.machine_class,
      is_active = true,
      canonical_process_id = EXCLUDED.canonical_process_id;
END
$calc$;

-- Machining - Rough Turning
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Machining - Rough Turning$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Machining - Rough Turning$q$, 'process', 'single', false, true, true, $q$Rough turning from the bar down to the diameter the finish cut starts at, as the Machining calculator workbook's Turning sheet times it: n = 1000 v / (pi D) at the bar diameter, capped at the machine's spindle limit; passes = (bar - finish start diameter) / (2 x depth of cut), rounded up to whole passes (the sheet leaves a fraction); time = (turned length + 10 mm) / (feed x n) x passes, rounded up to whole seconds. Cutting speed and feed from the workbook's Turning cutting conditions (carbide, the band holding the depth of cut), picked at the Range Position.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$Rough turning from the bar down to the diameter the finish cut starts at, as the Machining calculator workbook's Turning sheet times it: n = 1000 v / (pi D) at the bar diameter, capped at the machine's spindle limit; passes = (bar - finish start diameter) / (2 x depth of cut), rounded up to whole passes (the sheet leaves a fraction); time = (turned length + 10 mm) / (feed x n) x passes, rounded up to whole seconds. Cutting speed and feed from the workbook's Turning cutting conditions (carbide, the band holding the depth of cut), picked at the Range Position.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Turned Diameter$q$, $q$Turned Diameter (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Turned Length$q$, $q$Turned Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Bar Diameter$q$, $q$Bar Diameter (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Rough Depth of Cut$q$, $q$Rough Depth of Cut (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, $q$2$q$, 4, true),
    (v_id, $q$Finish Depth of Cut$q$, $q$Finish Depth of Cut (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, $q$0.5$q$, 5, true),
    (v_id, $q$Rough Speed Min$q$, $q$Rough Speed Min (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblTurningConditions$q$, $q$SpeedMinMPerMin$q$, NULL, 6, true),
    (v_id, $q$Rough Speed Max$q$, $q$Rough Speed Max (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblTurningConditions$q$, $q$SpeedMaxMPerMin$q$, NULL, 7, true),
    (v_id, $q$Rough Feed Min$q$, $q$Rough Feed Min (mm/rev)$q$, $q$number$q$, $q$mm/rev$q$, $q$machining_lookup$q$, $q$tblTurningConditions$q$, $q$FeedMinMmPerRev$q$, NULL, 8, true),
    (v_id, $q$Rough Feed Max$q$, $q$Rough Feed Max (mm/rev)$q$, $q$number$q$, $q$mm/rev$q$, $q$machining_lookup$q$, $q$tblTurningConditions$q$, $q$FeedMaxMmPerRev$q$, NULL, 9, true),
    (v_id, $q$Range Position$q$, $q$Range Position$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$0.3$q$, 10, true),
    (v_id, $q$Max Spindle Speed$q$, $q$Max Spindle Speed (rpm)$q$, $q$number$q$, $q$rpm$q$, NULL, NULL, NULL, NULL, 11, true),
    (v_id, $q$Approach Length$q$, $q$Approach Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, $q$10$q$, 12, true),
    (v_id, $q$Rough Cutting Speed$q$, $q$Rough Cutting Speed (m/min)$q$, $q$calculated$q$, $q$m/min$q$, NULL, NULL, NULL, $q${Rough Speed Min} + {Range Position} * ({Rough Speed Max} - {Rough Speed Min})$q$, 13, false),
    (v_id, $q$Rough Feed$q$, $q$Rough Feed (mm/rev)$q$, $q$calculated$q$, $q$mm/rev$q$, NULL, NULL, NULL, $q${Rough Feed Min} + {Range Position} * ({Rough Feed Max} - {Rough Feed Min})$q$, 14, false),
