-- Machining - Facing
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Machining - Facing$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Machining - Facing$q$, 'process', 'single', false, true, true, $q$Facing the stock piece's faces down to the part, as the Machining calculator workbook's Face Milling sheet times it: n = 1000 v / (pi D), capped at the machine's spindle limit; width passes = (face width - D / 2) / (D - 2) and depth passes = stock depth / depth of cut, each rounded up to whole passes (the sheet leaves both fractional); time = (face length + 10 mm + D / 2) / (feed per tooth x teeth x n) x width passes x depth passes, rounded up to whole seconds a face. Cutting speed and feed per tooth from the workbook's milling conditions for the material; the face mill and the depth of cut are the sheet's own. The faces and the stock on them are the stock model's: a block's top and bottom, a bar's two sawn ends. The workbook prices no face mill. (It replaces a fixed 45 s a part.)$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$Facing the stock piece's faces down to the part, as the Machining calculator workbook's Face Milling sheet times it: n = 1000 v / (pi D), capped at the machine's spindle limit; width passes = (face width - D / 2) / (D - 2) and depth passes = stock depth / depth of cut, each rounded up to whole passes (the sheet leaves both fractional); time = (face length + 10 mm + D / 2) / (feed per tooth x teeth x n) x width passes x depth passes, rounded up to whole seconds a face. Cutting speed and feed per tooth from the workbook's milling conditions for the material; the face mill and the depth of cut are the sheet's own. The faces and the stock on them are the stock model's: a block's top and bottom, a bar's two sawn ends. The workbook prices no face mill. (It replaces a fixed 45 s a part.)$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Face Length$q$, $q$Face Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Face Width$q$, $q$Face Width (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
