-- Machining - Rough Milling
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Machining - Rough Milling$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Machining - Rough Milling$q$, 'process', 'single', false, true, true, $q$Roughing a pocket or a flat with an end mill, as the Machining calculator workbook's End Milling sheet times it: n = 1000 v / (pi D), capped at the machine's spindle limit; width passes = (cut width - D / 2) / stepover and depth passes = cut depth / depth of cut, each rounded up to whole passes (the sheet leaves both fractional); time = (cut length + 10 mm + D / 2) / (feed per tooth x teeth x n) x width passes x depth passes, rounded up to whole seconds a cut. The stepover is the sheet's D - 2 mm, never less than half the cutter (below a 4 mm cutter D - 2 would leave the cutter overlapping itself, or no stepover at all). Cutting speed and feed per tooth from the workbook's milling conditions for the material; the cutter is the material's end mill (tblMillingFinishing), or the cut's width when walls confine it to less; the depth of cut is the sheet's own; the end mill's price and life from the workbook. (It replaces the removed volume at the material removal rate, 80 % roughed and 20 % at 0.4 of the rate.)$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$Roughing a pocket or a flat with an end mill, as the Machining calculator workbook's End Milling sheet times it: n = 1000 v / (pi D), capped at the machine's spindle limit; width passes = (cut width - D / 2) / stepover and depth passes = cut depth / depth of cut, each rounded up to whole passes (the sheet leaves both fractional); time = (cut length + 10 mm + D / 2) / (feed per tooth x teeth x n) x width passes x depth passes, rounded up to whole seconds a cut. The stepover is the sheet's D - 2 mm, never less than half the cutter (below a 4 mm cutter D - 2 would leave the cutter overlapping itself, or no stepover at all). Cutting speed and feed per tooth from the workbook's milling conditions for the material; the cutter is the material's end mill (tblMillingFinishing), or the cut's width when walls confine it to less; the depth of cut is the sheet's own; the end mill's price and life from the workbook. (It replaces the removed volume at the material removal rate, 80 % roughed and 20 % at 0.4 of the rate.)$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
