    (v_id, $q$Teeth$q$, $q$Teeth$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Speed Min$q$, $q$Speed Min (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$SpeedMinMPerMin$q$, NULL, 7, true),
    (v_id, $q$Speed Max$q$, $q$Speed Max (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$SpeedMaxMPerMin$q$, NULL, 8, true),
    (v_id, $q$Feed per Tooth Min$q$, $q$Feed per Tooth Min (mm/tooth)$q$, $q$number$q$, $q$mm/tooth$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$FeedPerToothMinMm$q$, NULL, 9, true),
    (v_id, $q$Feed per Tooth Max$q$, $q$Feed per Tooth Max (mm/tooth)$q$, $q$number$q$, $q$mm/tooth$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$FeedPerToothMaxMm$q$, NULL, 10, true),
    (v_id, $q$Range Position$q$, $q$Range Position$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$0.3$q$, 11, true),
