    (v_id, $q$Time per Cut$q$, $q$Time per Cut (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$ceil({Machining Time} * 60)$q$, 22, false),
    (v_id, $q$Tool Price$q$, $q$Tool Price (INR)$q$, $q$number$q$, $q$INR$q$, $q$machining_lookup$q$, $q$tblCuttingToolCost$q$, $q$PriceInr$q$, NULL, 23, true),
    (v_id, $q$Tool Life$q$, $q$Tool Life (parts)$q$, $q$number$q$, $q$parts$q$, $q$machining_lookup$q$, $q$tblCuttingToolCost$q$, $q$ToolLifeParts$q$, NULL, 24, true),
