-- Machining - Slot Milling
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Machining - Slot Milling$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Machining - Slot Milling$q$, 'process', 'single', false, true, true, $q$Milling a slot out with an end mill, as the Machining calculator workbook's Slot Milling sheet times it: n = 1000 v / (pi D), capped at the machine's spindle limit; depth passes = slot depth / depth of cut and width passes = slot width / D, each rounded up; time = (slot length + 10 mm + D) / (feed per tooth x teeth x n) x depth passes x width passes, rounded up to whole seconds a slot. The depth of cut is the slotting depth ratio of the cutter: its whole diameter a pass, the slot milling depth of the end milling table pasted on the sheet (axial depth of cut 1 x D), which cuts the sheet's own example (6.5 mm deep with a 12 mm cutter) in its one pass. (Half the cutter until migration 1157, which took the sheet's example in two passes: 43 s for its 22 s.) Cutting speed and feed per tooth from the workbook's milling conditions for the material; the cutter is the slot's width, or the material's end mill (tblMillingFinishing) when the slot is wider; the end mill's price and life from the workbook. The engine also times the slot by Plunge Milling and keeps the quicker. (It replaces the slot's volume at the material removal rate plus 20 s a slot.)$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$Milling a slot out with an end mill, as the Machining calculator workbook's Slot Milling sheet times it: n = 1000 v / (pi D), capped at the machine's spindle limit; depth passes = slot depth / depth of cut and width passes = slot width / D, each rounded up; time = (slot length + 10 mm + D) / (feed per tooth x teeth x n) x depth passes x width passes, rounded up to whole seconds a slot. The depth of cut is the slotting depth ratio of the cutter: its whole diameter a pass, the slot milling depth of the end milling table pasted on the sheet (axial depth of cut 1 x D), which cuts the sheet's own example (6.5 mm deep with a 12 mm cutter) in its one pass. (Half the cutter until migration 1157, which took the sheet's example in two passes: 43 s for its 22 s.) Cutting speed and feed per tooth from the workbook's milling conditions for the material; the cutter is the slot's width, or the material's end mill (tblMillingFinishing) when the slot is wider; the end mill's price and life from the workbook. The engine also times the slot by Plunge Milling and keeps the quicker. (It replaces the slot's volume at the material removal rate plus 20 s a slot.)$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Slot Length$q$, $q$Slot Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Slot Width$q$, $q$Slot Width (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Slot Depth$q$, $q$Slot Depth (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Slots$q$, $q$Slots$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Cutter Diameter$q$, $q$Cutter Diameter (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Teeth$q$, $q$Teeth$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Speed Min$q$, $q$Speed Min (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$SpeedMinMPerMin$q$, NULL, 7, true),
    (v_id, $q$Speed Max$q$, $q$Speed Max (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$SpeedMaxMPerMin$q$, NULL, 8, true),
    (v_id, $q$Feed per Tooth Min$q$, $q$Feed per Tooth Min (mm/tooth)$q$, $q$number$q$, $q$mm/tooth$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$FeedPerToothMinMm$q$, NULL, 9, true),
    (v_id, $q$Feed per Tooth Max$q$, $q$Feed per Tooth Max (mm/tooth)$q$, $q$number$q$, $q$mm/tooth$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$FeedPerToothMaxMm$q$, NULL, 10, true),
    (v_id, $q$Range Position$q$, $q$Range Position$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$0.3$q$, 11, true),
    (v_id, $q$Max Spindle Speed$q$, $q$Max Spindle Speed (rpm)$q$, $q$number$q$, $q$rpm$q$, NULL, NULL, NULL, NULL, 12, true),
    (v_id, $q$Slotting Depth Ratio$q$, $q$Slotting Depth Ratio$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$1$q$, 13, true),
    (v_id, $q$Approach Length$q$, $q$Approach Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, $q$10$q$, 14, true),
    (v_id, $q$Cutting Speed$q$, $q$Cutting Speed (m/min)$q$, $q$calculated$q$, $q$m/min$q$, NULL, NULL, NULL, $q${Speed Min} + {Range Position} * ({Speed Max} - {Speed Min})$q$, 15, false),
    (v_id, $q$Feed per Tooth$q$, $q$Feed per Tooth (mm/tooth)$q$, $q$calculated$q$, $q$mm/tooth$q$, NULL, NULL, NULL, $q${Feed per Tooth Min} + {Range Position} * ({Feed per Tooth Max} - {Feed per Tooth Min})$q$, 16, false),
    (v_id, $q$Spindle Speed$q$, $q$Spindle Speed (rpm)$q$, $q$calculated$q$, $q$rpm$q$, NULL, NULL, NULL, $q$min({Max Spindle Speed}, {Cutting Speed} * 1000 / (pi * {Cutter Diameter}))$q$, 17, false),
    (v_id, $q$Depth of Cut$q$, $q$Depth of Cut (mm)$q$, $q$calculated$q$, $q$mm$q$, NULL, NULL, NULL, $q${Slotting Depth Ratio} * {Cutter Diameter}$q$, 18, false),
    (v_id, $q$Depth Passes$q$, $q$Depth Passes$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$max(1, ceil({Slot Depth} / {Depth of Cut}))$q$, 19, false),
