    (v_id, $q$Machining Time$q$, $q$Machining Time (min)$q$, $q$calculated$q$, $q$min$q$, NULL, NULL, NULL, $q$({Slot Length} + {Approach Length} + {Cutter Diameter}) / ({Feed per Tooth} * {Teeth} * {Spindle Speed}) * {Depth Passes} * {Width Passes}$q$, 21, false),
    (v_id, $q$Time per Slot$q$, $q$Time per Slot (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$ceil({Machining Time} * 60)$q$, 22, false),
    (v_id, $q$Tool Price$q$, $q$Tool Price (INR)$q$, $q$number$q$, $q$INR$q$, $q$machining_lookup$q$, $q$tblCuttingToolCost$q$, $q$PriceInr$q$, NULL, 23, true),
    (v_id, $q$Tool Life$q$, $q$Tool Life (parts)$q$, $q$number$q$, $q$parts$q$, $q$machining_lookup$q$, $q$tblCuttingToolCost$q$, $q$ToolLifeParts$q$, NULL, 24, true),
    (v_id, $q$Tool Cost per Part$q$, $q$Tool Cost per Part (INR)$q$, $q$calculated$q$, $q$INR$q$, NULL, NULL, NULL, $q${Tool Price} / {Tool Life}$q$, 25, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Slots} * {Time per Slot}$q$, 26, false);

  INSERT INTO public.process_calculator_mappings
    (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
  SELECT 'Machining', s.station, $q$Slot Milling$q$, v_id, $q$Machining - Slot Milling$q$, true, 739, s.cls,
         (SELECT pt.id FROM public.process_taxonomy pt WHERE pt.process_group = 'Machining' AND pt.process_name = s.station LIMIT 1)
  FROM (VALUES ($q$2_axis_lathe$q$, $q$2 Axis Lathe$q$), ($q$3_axis_lathe$q$, $q$3 Axis Lathe$q$), ($q$2_axis_bar_feed_lathe_with_sub_spindle$q$, $q$2 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$3_axis_bar_feed_lathe_with_sub_spindle$q$, $q$3 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$simultaneous_turning$q$, $q$Simultaneous Turning$q$), ($q$machining_millturn$q$, $q$MillTurn$q$), ($q$3_axis_mill$q$, $q$3 Axis Mill$q$), ($q$4_axis_mill$q$, $q$4 Axis Mill$q$), ($q$5_axis_mill$q$, $q$5 Axis Mill$q$)) AS s(cls, station)
