    VALUES (NULL, $q$Machining - Center Drilling$q$, 'process', 'single', false, true, true, $q$Spotting each hole before it is drilled, timed as the Machining calculator workbook (memory/Machining - Calculator Database (1).xlsx) times a drill (its Drilling sheet): n = 1000 v / (pi D) at the hole's diameter, capped at the machine's spindle limit; the spot is cut to the hole's diameter, which a 90 degree spot drill reaches at half that diameter deep; time = (spot depth + 10 mm) / (feed x n), rounded up to whole seconds a hole. The speed and feed are the workbook's drilling ones for the material and diameter (tblDrillReamData). Was a flat 5 s a hole (user decision 2026-11-25: every machining step on the workbook's method).$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$Spotting each hole before it is drilled, timed as the Machining calculator workbook (memory/Machining - Calculator Database (1).xlsx) times a drill (its Drilling sheet): n = 1000 v / (pi D) at the hole's diameter, capped at the machine's spindle limit; the spot is cut to the hole's diameter, which a 90 degree spot drill reaches at half that diameter deep; time = (spot depth + 10 mm) / (feed x n), rounded up to whole seconds a hole. The speed and feed are the workbook's drilling ones for the material and diameter (tblDrillReamData). Was a flat 5 s a hole (user decision 2026-11-25: every machining step on the workbook's method).$q$, updated_at = now() WHERE id = v_id;
