    (v_id, $q$Feed$q$, $q$Feed (mm/rev)$q$, $q$number$q$, $q$mm/rev$q$, $q$machining_lookup$q$, $q$tblDrillReamData$q$, $q$FeedMmPerRev$q$, NULL, 5, true),
    (v_id, $q$Range Position$q$, $q$Range Position$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$0.3$q$, 6, true),
    (v_id, $q$Max Spindle Speed$q$, $q$Max Spindle Speed (rpm)$q$, $q$number$q$, $q$rpm$q$, NULL, NULL, NULL, NULL, 7, true),
