-- Machining - End Facing
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Machining - End Facing$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Machining - End Facing$q$, 'process', 'single', false, true, true, $q$Facing each end of a turned part square, as the Machining calculator workbook's Facing sheet times it: n = 1000 v / (pi D) at the bar diameter, capped at the machine's spindle limit; passes = facing stock / depth of cut, rounded up (at least one cleanup pass); time per face = (length of cut + 10 mm) / (feed x n) x passes, rounded up to whole seconds; both ends. Correction: the length of cut is the bar's radius, the tool's travel from the bar surface to the centre (the sheet types 13 mm for a 50 mm bar). Cutting speed and feed from the workbook's Turning cutting conditions (carbide, the band holding the depth of cut); tool price and life from the sheet.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$Facing each end of a turned part square, as the Machining calculator workbook's Facing sheet times it: n = 1000 v / (pi D) at the bar diameter, capped at the machine's spindle limit; passes = facing stock / depth of cut, rounded up (at least one cleanup pass); time per face = (length of cut + 10 mm) / (feed x n) x passes, rounded up to whole seconds; both ends. Correction: the length of cut is the bar's radius, the tool's travel from the bar surface to the centre (the sheet types 13 mm for a 50 mm bar). Cutting speed and feed from the workbook's Turning cutting conditions (carbide, the band holding the depth of cut); tool price and life from the sheet.$q$, updated_at = now() WHERE id = v_id;
