-- Machining - Plunge Milling
DO $calc$
DECLARE v_id UUID;
BEGIN
  SELECT id INTO v_id FROM public.calculators WHERE name = $q$Machining - Plunge Milling$q$ AND user_id IS NULL AND retired_at IS NULL;
  IF v_id IS NULL THEN
    INSERT INTO public.calculators (user_id, name, calc_category, calculator_type, is_template, is_public, is_global, description)
    VALUES (NULL, $q$Machining - Plunge Milling$q$, 'process', 'single', false, true, true, $q$Milling a slot out by plunging the end mill straight down, step after step along it, as the Machining calculator workbook's Plunge Milling sheet means it, corrected: the sheet copies the Slot Milling formula with a length of cut of 3.7 x 3.142 x 10 mm. Plunges = slot length / (plunge step ratio x D) and width passes = slot width / D, each rounded up; each plunge feeds the slot depth + 10 mm at feed per tooth x teeth x n; n = 1000 v / (pi D), capped at the machine's spindle limit; rounded up to whole seconds a slot. Cutting speed and feed per tooth from the workbook's milling conditions for the material; the end mill's price and life from the workbook. The engine times every slot both ways and keeps the quicker: plunging wins on a deep slot.$q$)
    RETURNING id INTO v_id;
  ELSE
    UPDATE public.calculators SET description = $q$Milling a slot out by plunging the end mill straight down, step after step along it, as the Machining calculator workbook's Plunge Milling sheet means it, corrected: the sheet copies the Slot Milling formula with a length of cut of 3.7 x 3.142 x 10 mm. Plunges = slot length / (plunge step ratio x D) and width passes = slot width / D, each rounded up; each plunge feeds the slot depth + 10 mm at feed per tooth x teeth x n; n = 1000 v / (pi D), capped at the machine's spindle limit; rounded up to whole seconds a slot. Cutting speed and feed per tooth from the workbook's milling conditions for the material; the end mill's price and life from the workbook. The engine times every slot both ways and keeps the quicker: plunging wins on a deep slot.$q$, updated_at = now() WHERE id = v_id;
  END IF;

  DELETE FROM public.calculator_fields WHERE calculator_id = v_id;
  INSERT INTO public.calculator_fields
    (calculator_id, field_name, display_label, field_type, unit, data_source, source_table, source_field, default_value, display_order, is_required)
  VALUES
    (v_id, $q$Slot Length$q$, $q$Slot Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 1, true),
    (v_id, $q$Slot Width$q$, $q$Slot Width (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 2, true),
    (v_id, $q$Slot Depth$q$, $q$Slot Depth (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 3, true),
    (v_id, $q$Slots$q$, $q$Slots$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 4, true),
    (v_id, $q$Cutter Diameter$q$, $q$Cutter Diameter (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, NULL, 5, true),
    (v_id, $q$Teeth$q$, $q$Teeth$q$, $q$number$q$, NULL, NULL, NULL, NULL, NULL, 6, true),
    (v_id, $q$Speed Min$q$, $q$Speed Min (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$SpeedMinMPerMin$q$, NULL, 7, true),
    (v_id, $q$Speed Max$q$, $q$Speed Max (m/min)$q$, $q$number$q$, $q$m/min$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$SpeedMaxMPerMin$q$, NULL, 8, true),
    (v_id, $q$Feed per Tooth Min$q$, $q$Feed per Tooth Min (mm/tooth)$q$, $q$number$q$, $q$mm/tooth$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$FeedPerToothMinMm$q$, NULL, 9, true),
    (v_id, $q$Feed per Tooth Max$q$, $q$Feed per Tooth Max (mm/tooth)$q$, $q$number$q$, $q$mm/tooth$q$, $q$machining_lookup$q$, $q$tblMillingConditions$q$, $q$FeedPerToothMaxMm$q$, NULL, 10, true),
    (v_id, $q$Range Position$q$, $q$Range Position$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$0.3$q$, 11, true),
    (v_id, $q$Max Spindle Speed$q$, $q$Max Spindle Speed (rpm)$q$, $q$number$q$, $q$rpm$q$, NULL, NULL, NULL, NULL, 12, true),
    (v_id, $q$Plunge Step Ratio$q$, $q$Plunge Step Ratio$q$, $q$number$q$, NULL, NULL, NULL, NULL, $q$0.75$q$, 13, true),
    (v_id, $q$Approach Length$q$, $q$Approach Length (mm)$q$, $q$number$q$, $q$mm$q$, NULL, NULL, NULL, $q$10$q$, 14, true),
    (v_id, $q$Cutting Speed$q$, $q$Cutting Speed (m/min)$q$, $q$calculated$q$, $q$m/min$q$, NULL, NULL, NULL, $q${Speed Min} + {Range Position} * ({Speed Max} - {Speed Min})$q$, 15, false),
    (v_id, $q$Feed per Tooth$q$, $q$Feed per Tooth (mm/tooth)$q$, $q$calculated$q$, $q$mm/tooth$q$, NULL, NULL, NULL, $q${Feed per Tooth Min} + {Range Position} * ({Feed per Tooth Max} - {Feed per Tooth Min})$q$, 16, false),
    (v_id, $q$Spindle Speed$q$, $q$Spindle Speed (rpm)$q$, $q$calculated$q$, $q$rpm$q$, NULL, NULL, NULL, $q$min({Max Spindle Speed}, {Cutting Speed} * 1000 / (pi * {Cutter Diameter}))$q$, 17, false),
    (v_id, $q$Plunges$q$, $q$Plunges$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$max(1, ceil({Slot Length} / ({Plunge Step Ratio} * {Cutter Diameter})))$q$, 18, false),
    (v_id, $q$Width Passes$q$, $q$Width Passes$q$, $q$calculated$q$, NULL, NULL, NULL, NULL, $q$max(1, ceil({Slot Width} / {Cutter Diameter}))$q$, 19, false),
    (v_id, $q$Machining Time$q$, $q$Machining Time (min)$q$, $q$calculated$q$, $q$min$q$, NULL, NULL, NULL, $q${Plunges} * {Width Passes} * ({Slot Depth} + {Approach Length}) / ({Feed per Tooth} * {Teeth} * {Spindle Speed})$q$, 20, false),
    (v_id, $q$Time per Slot$q$, $q$Time per Slot (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q$ceil({Machining Time} * 60)$q$, 21, false),
    (v_id, $q$Tool Price$q$, $q$Tool Price (INR)$q$, $q$number$q$, $q$INR$q$, $q$machining_lookup$q$, $q$tblCuttingToolCost$q$, $q$PriceInr$q$, NULL, 22, true),
    (v_id, $q$Tool Life$q$, $q$Tool Life (parts)$q$, $q$number$q$, $q$parts$q$, $q$machining_lookup$q$, $q$tblCuttingToolCost$q$, $q$ToolLifeParts$q$, NULL, 23, true),
    (v_id, $q$Tool Cost per Part$q$, $q$Tool Cost per Part (INR)$q$, $q$calculated$q$, $q$INR$q$, NULL, NULL, NULL, $q${Tool Price} / {Tool Life}$q$, 24, false),
    (v_id, $q$Cycle Time$q$, $q$Cycle Time (s)$q$, $q$calculated$q$, $q$s$q$, NULL, NULL, NULL, $q${Slots} * {Time per Slot}$q$, 25, false);

  INSERT INTO public.process_calculator_mappings
    (process_group, process_route, operation, calculator_id, calculator_name, is_active, display_order, machine_class, canonical_process_id)
  SELECT 'Machining', s.station, $q$Plunge Milling$q$, v_id, $q$Machining - Plunge Milling$q$, true, 760, s.cls,
         (SELECT pt.id FROM public.process_taxonomy pt WHERE pt.process_group = 'Machining' AND pt.process_name = s.station LIMIT 1)
  FROM (VALUES ($q$2_axis_lathe$q$, $q$2 Axis Lathe$q$), ($q$3_axis_lathe$q$, $q$3 Axis Lathe$q$), ($q$2_axis_bar_feed_lathe_with_sub_spindle$q$, $q$2 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$3_axis_bar_feed_lathe_with_sub_spindle$q$, $q$3 Axis Bar Feed Lathe with Sub Spindle$q$), ($q$simultaneous_turning$q$, $q$Simultaneous Turning$q$), ($q$machining_millturn$q$, $q$MillTurn$q$), ($q$3_axis_mill$q$, $q$3 Axis Mill$q$), ($q$4_axis_mill$q$, $q$4 Axis Mill$q$), ($q$5_axis_mill$q$, $q$5 Axis Mill$q$)) AS s(cls, station)
  ON CONFLICT (process_group, process_route, operation) DO UPDATE
  SET calculator_id = EXCLUDED.calculator_id,
      calculator_name = EXCLUDED.calculator_name,
      machine_class = EXCLUDED.machine_class,
      is_active = true,
      canonical_process_id = EXCLUDED.canonical_process_id;
END
$calc$;

DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Machining - Drilling$q$, 17, 9),
    ($q$Machining - Rough Turning$q$, 19, 6),
    ($q$Machining - Finish Turning$q$, 17, 6),
    ($q$Machining - Reaming$q$, 15, 9),
    ($q$Machining - Rigid Tapping$q$, 17, 9),
    ($q$Machining - Milling$q$, 18, 9),
    ($q$Machining - Drill Press$q$, 17, 1),
    ($q$Machining - Stock Prep Mill$q$, 18, 1),
    ($q$Machining - Stock Prep Lathe$q$, 19, 1),
    ($q$Machining - Facing$q$, 22, 9),
    ($q$Machining - Rough Milling$q$, 26, 9),
    ($q$Machining - Bulk Milling$q$, 5, 9),
    ($q$Machining - Fine Finish Milling$q$, 14, 9),
    ($q$Machining - Contouring$q$, 15, 9),
    ($q$Machining - Perimeter Milling$q$, 15, 9),
    ($q$Machining - Slot Milling$q$, 26, 9),
    ($q$Machining - Center Drilling$q$, 14, 9),
    ($q$Machining - Chamfering$q$, 17, 9),
    ($q$Machining - Filleting$q$, 17, 9),
    ($q$Machining - Countersinking$q$, 15, 9),
    ($q$Machining - Obround Slot Milling$q$, 14, 7),
    ($q$Machining - End Facing$q$, 22, 6),
    ($q$Machining - Thread Turning$q$, 15, 6),
    ($q$Machining - Knurling$q$, 14, 6),
    ($q$Machining - Step Drilling$q$, 17, 9),
    ($q$Machining - Internal Boring$q$, 22, 6),
    ($q$Machining - Boring$q$, 22, 3),
    ($q$Machining - Plunge Milling$q$, 25, 9)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.is_active) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 1158: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
